import { tag } from "@tinker/core";

export declare namespace ConsoleOutput {
  /** `fd` lets a telemetry worker write the same lines straight to the descriptor. */
  type Sink = { writableNeedDrain?: boolean; fd?: number; write(text: string): unknown };
  type Methods = {
    error(value: unknown): void;
    warn(value: unknown): void;
    info(value: unknown): void;
  };
}

/**
 * Where a server root writes its JSON log lines. The command binds the host's stdout stream
 * (ADR 0113); a root with none writes no lines.
 */
export const consoleOutput = tag<ConsoleOutput.Sink | null>({
  label: "telemetry.console",
  default: null,
});

/** Where a tab shows its log records. The browser command binds the tab's `console` (ADR 0113). */
export const logConsole = tag<ConsoleOutput.Methods | null>({
  label: "telemetry.logConsole",
  default: null,
});

import { resource } from "@tinker/core";

import { httpBackend } from "~/components/http";

import type { Telemetry } from "./records";
import { logsUrl, telemetryService, telemetrySide, tracesUrl } from "./settings";

/** Sends cached JSON without observing its own HTTP requests (ADR 0102). */
export const delivery = resource({
  label: "telemetry.delivery",
  depends: {
    side: telemetrySide,
    service: telemetryService,
    tracesUrl: tracesUrl.optional,
    logsUrl: logsUrl.optional,
    backend: httpBackend,
  },
  factory: ({ side, service, tracesUrl, logsUrl, backend }, ctx) => {
    let traces: URL | undefined;
    let logs: URL | undefined;
    if (side !== "browser") {
      if (!tracesUrl.present) return ctx.raise("MissingTag", { label: "telemetry.tracesUrl" });
      if (!logsUrl.present) return ctx.raise("MissingTag", { label: "telemetry.logsUrl" });

      traces = tracesUrl.value;
      logs = new URL(logsUrl.value);
      logs.searchParams.set("_time_field", "time");
      logs.searchParams.set("_msg_field", "msg");
      logs.searchParams.set("_stream_fields", "service,side");
    }

    return {
      async send(records: Telemetry.Record[], signal: AbortSignal): Promise<Telemetry.Delivery> {
        const browser = side === "browser";
        let batches: { url: string; body: string | undefined; contentType: string }[];
        if (browser) {
          const traces = records
            .filter((record) => record.kind === "trace")
            .map((record) => `{"side":"${record.side}",${record.json.slice(1)}`);
          const lines = records
            .filter((record) => record.kind === "log")
            .map((record) => record.json);
          batches = [
            {
              url: "/api/telemetry",
              body: `{"traces":[${traces.join(",")}],"logs":[${lines.join(",")}]}`,
              contentType: "application/json",
            },
          ];
        } else {
          const groups = ["server", "browser", "ssr", "worker"].flatMap((side) => {
            const spans = records
              .filter((record) => record.kind === "trace" && record.side === side)
              .map((record) => record.json);
            if (!spans.length) return [];

            const resource = JSON.stringify({
              attributes: [
                { key: "service.name", value: { stringValue: service } },
                { key: "tinker.side", value: { stringValue: side } },
              ],
            });
            return [
              `{"resource":${resource},"scopeSpans":[{"scope":{"name":"tinker.start"},"spans":[${spans.join(",")}]}]}`,
            ];
          });
          const lines = records
            .filter((record) => record.kind === "log")
            .map((record) => record.json);
          batches = [
            {
              url: traces!.href,
              body: groups.length ? `{"resourceSpans":[${groups.join(",")}]}` : undefined,
              contentType: "application/json",
            },
            {
              url: logs!.href,
              body: lines.length ? lines.join("\n") : undefined,
              contentType: "application/stream+json",
            },
          ];
        }

        const accepted = await Promise.all(
          batches.map(async ({ url, body, contentType }) => {
            if (body === undefined) return true;
            try {
              const response = await backend(url, {
                method: "POST",
                headers: { "content-type": contentType },
                body,
                signal,
                redirect: "error",
                ...(browser ? { credentials: "same-origin", keepalive: true } : {}),
              });
              await response.body?.cancel();
              return response.ok;
            } catch {
              return false;
            }
          }),
        );
        return { traces: accepted[0]!, logs: browser ? accepted[0]! : accepted[1]! };
      },
    };
  },
});

import { LEVELS, resource } from "@tinker/core";

import { exportHealth } from "./health";
import { queue } from "./queue";
import { encodeValue, spanBody } from "./records";
import type { Telemetry } from "./records";
import { telemetryService } from "./settings";

type SpanLine = Extract<Telemetry.Wire, [tag: "s", ...rest: unknown[]]>;
type LogLine = Extract<Telemetry.Wire, [tag: "l", ...rest: unknown[]]>;

/**
 * Worker side: one wire line becomes the same queue records the in-process observer makes.
 * The worker's own root owns the queue, its batches, and the console mirror.
 * Health crosses threads only when its kind changes; every returned send changes it.
 */
export const threadDrain = resource({
  label: "telemetry.drain",
  depends: { queue, service: telemetryService, health: exportHealth.controller },
  factory: ({ queue, service, health }, ctx) => {
    let bad = 0;
    let changes = 0;
    let reported = -1;
    let changed: (() => void) | undefined;

    ctx.defer(
      health.watch((next, previous) => {
        if (next.kind === previous.kind) return;
        changes++;
        changed?.();
      }),
    );

    const owned = {
      /** The worker glue's wake-up: called on each kind change, so it can post soon after. */
      watch(listener: () => void) {
        changed = listener;
      },
      /** Health with unreadable lines counted as dropped. */
      health(): Telemetry.Health {
        const current = health.get();
        return { ...current, dropped: current.dropped + bad };
      },
      /** The health to post, or undefined when its kind has not changed since the last post. */
      report() {
        if (changes === reported) return undefined;
        reported = changes;
        return owned.health();
      },
      /** Sends what is queued now; the request side's `telemetryThread.flush` waits on it. */
      flush() {
        return queue.flush();
      },
      /** Sends what is left within the queue's 1.5 s close budget, then returns the final health. */
      async close() {
        await queue.close(true);
        return owned.health();
      },
      take(line: string) {
        let wire: Telemetry.Wire;
        try {
          wire = JSON.parse(line) as Telemetry.Wire;
        } catch {
          bad++;
          return;
        }

        if (wire[0] === "b") queue.ingest(wire[1]);
        else if (wire[0] === "s") owned.span(wire);
        else owned.log(wire);
      },
      span(wire: SpanLine) {
        const [, side, time, encoded, traceId, spanId, parentSpanId, sampled, name, kind] = wire;
        const [, , , , , , , , , , start, end, status, error, attributes, events] = wire;
        const span: Telemetry.SpanFields = {
          traceId,
          spanId,
          parentSpanId: parentSpanId ?? undefined,
          sampled,
          name,
          kind,
          start,
          end: end ?? undefined,
          status: status ?? undefined,
          error: error ?? undefined,
          attributes,
          events,
        };
        queue.add("trace", side, spanBody(span, encoded === 1));

        const record: Telemetry.Log = {
          level: LEVELS.info,
          time,
          service,
          side,
          traceId,
          spanId,
          attributes: undefined,
          msg: "core.span",
        };
        queue.writeConsole(queue.add("log", side, record), record);

        queue.publishQueued();
      },
      log(wire: LogLine) {
        const [, side, encoded, level, time, traceId, spanId, message, attributes] = wire;
        const record: Telemetry.Log = {
          level,
          time,
          service,
          side,
          traceId: traceId ?? undefined,
          spanId: spanId ?? undefined,
          attributes: Object.fromEntries(
            Object.entries(attributes).map(([key, value]) => [
              key.slice(0, 256),
              encoded ? (value as string) : encodeValue(value),
            ]),
          ),
          msg: message.slice(0, 2048),
        };
        queue.writeConsole(queue.add("log", side, record), record);

        queue.publishQueued();
      },
    };
    return owned;
  },
});

import { data } from "@tinker/core";

import type { Telemetry } from "./records";

/** What the telemetry queue holds, sends, and dropped; the queue alone writes it. */
export const exportHealth = data<Telemetry.Health>({
  label: "telemetry.exportHealth",
  initial: { kind: "idle", pending: 0, dropped: 0 },
});

import { namespace, resource } from "@tinker/core";

import { observer } from "./observer";
import { telemetrySide } from "./settings";

/** Each render has its own observer namespace; the tools queue remains shared. */
export const renderObserve = resource({ ...observer, target: "namespace" });
export const renderNs = namespace({ tags: [telemetrySide("ssr")] });

export type { Telemetry } from "./records";
export { observer, telemetryExport, ingestTelemetry, flushTelemetry } from "./observer";
export { consoleOutput, logConsole } from "./console";

export {
  telemetryBody,
  receiveTelemetry,
  browserIngest,
  browserTelemetry,
  telemetryOrigin,
} from "./ingest.server";

export { exportHealth } from "./health";

export {
  telemetrySide,
  telemetryService,
  tracesUrl,
  logsUrl,
  logLevel,
  spanHistory,
} from "./settings";

export {
  telemetryWorker,
  telemetryThread,
  threadRing,
  threadExport,
  threadObserver,
  threadRenderObserve,
  threadIngest,
} from "./thread.server";

export type { ThreadSettings, ThreadMessage, ThreadRing, ThreadWorker } from "./thread.server";
export { threadDrain } from "./drain.server";

export type { Telemetry } from "./records";
export { observer, telemetryExport, ingestTelemetry, flushTelemetry } from "./observer";
export { consoleOutput, logConsole } from "./console";
export { exportHealth } from "./health";

export {
  telemetrySide,
  telemetryService,
  tracesUrl,
  logsUrl,
  logLevel,
  spanHistory,
} from "./settings";

import { operation, resource, tag } from "@tinker/core";

import { raise } from "~/components/errors";
import { backendStop, requestStop } from "~/components/requests";
import { requestBody } from "~/components/requests/index.server";

import { ingestTelemetry } from "./observer";
import type { Telemetry } from "./records";
import { telemetryBatch } from "./records.server";
import { telemetryService } from "./settings";

/** Borrowed from the telemetry root; requests never close that owner. */
export const browserTelemetry = tag<(batch: Telemetry.Batch) => void>({
  label: "telemetry.browserIngest",
});

export const telemetryOrigin = tag<string | null>({ label: "telemetry.origin", default: null });

export const receiveTelemetry = operation({
  label: "telemetry.receive",
  depends: {
    ingest: browserTelemetry.required,
    backendStop: backendStop.required,
    requestStop: requestStop.required,
  },
  input: telemetryBatch,
  run: ({ ingest, backendStop, requestStop }, ctx) => {
    if (backendStop.aborted || requestStop.aborted || ctx.signal.aborted) raise("Cancelled", {});
    ingest(ctx.input);
  },
});

export const browserIngest = resource({
  label: "telemetry.browserIngest",
  depends: { ingest: ingestTelemetry.controller, service: telemetryService },
  factory: ({ ingest, service }) => ({
    ingest(this: void, batch: Telemetry.Batch) {
      for (const record of batch.logs) record.service = service;
      ingest.run({ input: batch });
    },
  }),
});

const browserBatch = telemetryBatch.refine(
  (batch) =>
    batch.logs.every((log) => log.side === "browser") &&
    batch.traces.every((span) => span.side === "browser"),
);

/** The request owns its reader and caps retained bytes before JSON or UTF-8 work. */
export const telemetryBody = resource({
  label: "telemetry.body",
  target: "session",
  depends: { bodyOwner: requestBody },
  factory: ({ bodyOwner }) => {
    const decoder = new TextDecoder("utf-8", { fatal: true });
    return {
      async read(body: ReadableStream<Uint8Array<ArrayBuffer>>): Promise<Telemetry.Batch | number> {
        const reader = bodyOwner.open(body);
        try {
          let length = 0;
          const chunks: Uint8Array<ArrayBuffer>[] = [];
          for (let next = await reader.read(); !next.done; next = await reader.read()) {
            length += next.value.byteLength;
            if (length > 65_536) {
              await reader.cancel();
              return 413;
            }
            chunks.push(next.value);
          }
          if (bodyOwner.signal.aborted) return 503;

          const bytes = new Uint8Array(length);
          let offset = 0;
          for (const chunk of chunks) {
            bytes.set(chunk, offset);
            offset += chunk.byteLength;
          }

          try {
            return browserBatch.parse(JSON.parse(decoder.decode(bytes)));
          } catch {
            return 400;
          }
        } finally {
          await bodyOwner.release();
        }
      },
    };
  },
});

import { resource } from "@tinker/core";

/** The server's telemetry root starts its worker thread from this module. */
export const workerThreads = resource({
  label: "module:node:worker_threads",
  target: "scope",
  factory: () => import("node:worker_threads"),
});

import { extension, LEVELS, operation, resource } from "@tinker/core";
import type { Observe } from "@tinker/core";

import { logConsole } from "./console";
import { queue } from "./queue";
import { encodeValue, spanBody } from "./records";
import type { Telemetry } from "./records";
import {
  logLevel,
  spanHistory,
  telemetryService,
  telemetrySide,
  tracesUrl,
  logsUrl,
} from "./settings";

/**
 * Transfers trusted records to the telemetry root; callers must not edit them afterward.
 * The server route validates outside data before this operation receives it.
 */
export const ingestTelemetry = operation({
  label: "telemetry.ingest",
  depends: { queue },
  input: (raw: unknown) => raw as Telemetry.Batch,
  run: ({ queue }, ctx) => queue.ingest(ctx.input),
});

export const flushTelemetry = operation({
  label: "telemetry.export",
  depends: { queue },
  run: ({ queue }) => queue.flush(),
});

/** On the telemetry root: the queue's timer starts with the root, and its close sends what is left. */
export const telemetryExport = extension({
  label: "telemetry",
  hooks: {
    async start(event) {
      const side = event.resolve(telemetrySide);
      event.resolve(telemetryService);
      if (side !== "browser") {
        event.resolve(tracesUrl);
        event.resolve(logsUrl);
      }

      const owned = event.resolve(queue);
      const flush = event.controller(flushTelemetry);
      owned.start(flush.run.bind(flush));
      await event.next();
    },
    async close(event) {
      await event.resolve(queue).close(true);
      return event.next();
    },
  },
});

/** Each native observer callback owns its queue and console work. */
export const observer = resource({
  label: "telemetry.observer",
  depends: {
    queue,
    service: telemetryService,
    side: telemetrySide,
    level: logLevel,
    history: spanHistory,
    show: logConsole,
  },
  factory: ({ queue, service, side, level, history, show }, ctx): Observe.Config => ({
    history,
    level,
    export(span) {
      queue.add("trace", side, spanBody(span, false));

      const record: Telemetry.Log = {
        level: LEVELS.info,
        time: ctx.clock.currentTimeMillis(),
        service,
        side,
        traceId: span.traceId,
        spanId: span.spanId,
        attributes: undefined,
        msg: "core.span",
      };
      const encoded = queue.add("log", side, record);
      if (side !== "browser") queue.writeConsole(encoded, record);
      else show?.info(record);
      queue.publishQueued();
    },
    log(entry) {
      const record: Telemetry.Log = {
        level: entry.level,
        time: entry.time,
        service,
        side,
        traceId: entry.span?.traceId,
        spanId: entry.span?.spanId,
        attributes: Object.fromEntries(
          Object.entries(entry.attributes).map(([key, value]) => [
            key.slice(0, 256),
            encodeValue(value),
          ]),
        ),
        msg: entry.message.slice(0, 2048),
      };
      const encoded = queue.add("log", side, record);
      if (side !== "browser") queue.writeConsole(encoded, record);
      else if (!show) {
        /* No console binding on this owner. */
      } else if (record.level >= LEVELS.error) show.error(record);
      else if (record.level >= LEVELS.warn) show.warn(record);
      else show.info(record);
      queue.publishQueued();
    },
  }),
});

import { resource } from "@tinker/core";

import { abortReasons } from "~/components/errors";

import { consoleOutput } from "./console";
import { delivery } from "./delivery";
import { exportHealth } from "./health";
import type { Telemetry } from "./records";
import { telemetrySide } from "./settings";

/** Retains failed records within count and byte bounds; this resource owns every promise. */
export const queue = resource({
  label: "telemetry.queue",
  target: "scope",
  depends: {
    side: telemetrySide,
    health: exportHealth.controller,
    delivery,
    console: consoleOutput,
  },
  factory: ({ side, health, delivery, console }, ctx) => {
    const encoder = new TextEncoder();
    let records: Telemetry.Record[] = [];
    const browser = side === "browser";
    const batchLimit = browser ? 32_000 : 48_000;
    /** Reserve the JSON envelope and one comma per browser record. */
    const recordLimit = browser ? batchLimit - 24 : batchLimit;
    const frameBytes = browser ? 23 : 0;
    const commaBytes = browser ? 1 : 0;
    const scratch = new Uint8Array(recordLimit + 4);

    const stdout = browser ? null : console;
    let consoleLines: string[] = [];
    let consoleBytes = 0;
    let draining = false;
    let queueBytes = 0;
    let dropped = 0;

    let timer: Promise<void> | undefined;
    let pending: Promise<void> | undefined;
    const stopTimer = new AbortController();
    const stopRequests = new AbortController();
    let state: "open" | "closing" | "closed" = "open";
    let publishing = true;
    let failed = false;

    const owned = {
      ingest(batch: Telemetry.Batch) {
        for (let index = 0; index < batch.traces.length; index++) {
          const { side, ...value } = batch.traces[index]!;
          owned.add("trace", side, value);
        }
        for (let index = 0; index < batch.logs.length; index++) {
          const value = batch.logs[index]!;
          owned.add("log", value.side, value);
        }
        if (batch.traces.length + batch.logs.length) owned.publishQueued();
      },
      add(
        kind: Telemetry.Record["kind"],
        side: Telemetry.Side,
        value: Telemetry.SpanBody | Telemetry.Log,
      ) {
        if (state === "closed" || records.length >= 512) {
          dropped++;
          return;
        }

        const json = JSON.stringify(value);
        const { read, written } = encoder.encodeInto(json, scratch);
        const bytes = written + (kind === "trace" ? side.length + 10 : 0);
        const record = { kind, side, json, bytes };

        if (read < json.length || bytes > recordLimit || queueBytes + bytes > 1_048_576) {
          dropped++;
        } else {
          records.push(record);
          queueBytes += bytes;
        }

        return record;
      },
      writeConsole(encoded: Telemetry.Record | undefined, value: Telemetry.Log) {
        if (state === "closed" || consoleLines.length >= 512 || consoleBytes >= 48_000) {
          dropped++;
          return;
        }
        if (!encoded) {
          const json = JSON.stringify(value);
          const size = encoder.encodeInto(json, scratch);
          if (size.read < json.length) {
            dropped++;
            return;
          }
          encoded = { kind: "log", side: value.side, json, bytes: size.written };
        }
        owned.retainConsole(encoded);
      },
      retainConsole(record: Telemetry.Record) {
        if (record.bytes + 1 > 48_000 - consoleBytes) {
          dropped++;
          return;
        }
        consoleLines.push(record.json);
        consoleBytes += record.bytes + 1;
      },
      flushConsole() {
        if (!stdout || stdout.writableNeedDrain || !consoleLines.length) return;
        stdout.write(`${consoleLines.join("\n")}\n`);
        consoleLines = [];
        consoleBytes = 0;
      },
      publishQueued() {
        if (publishing) {
          const previous = health.get();
          health.set(
            previous.kind === "failed"
              ? { ...previous, pending: records.length, dropped }
              : { kind: pending ? "sending" : "queued", pending: records.length, dropped },
          );
        }
        if (state === "open" && (records.length >= 64 || queueBytes >= batchLimit)) {
          draining = true;
          pending ??= owned.flush();
        }
      },
      start(flush: () => Promise<void>) {
        if (side !== "ssr") {
          timer = Promise.resolve().then(async () => {
            while (!stopTimer.signal.aborted) {
              try {
                await ctx.clock.sleep(1000, stopTimer.signal);
              } catch (error) {
                if (!stopTimer.signal.aborted) throw error;
                return;
              }
              if (!stopTimer.signal.aborted) await flush();
            }
          });
        }
      },
      takeBatch() {
        let bytes = frameBytes;
        const retained: typeof records = [];
        for (const record of records.slice(0, 64)) {
          const size = record.bytes + commaBytes;
          if (bytes + size > batchLimit) continue;
          bytes += size;
          retained.push(record);
        }
        return retained;
      },
      flush(): Promise<void> {
        if (!records.length && !pending) {
          owned.flushConsole();
          return Promise.resolve();
        }
        return (pending ??= Promise.resolve().then(async () => {
          try {
            do {
              owned.flushConsole();
              if (!records.length || stopRequests.signal.aborted) return;
              await owned.sendBatch();
            } while (draining && records.length && !failed);
          } finally {
            pending = undefined;
            draining = false;
          }
        }));
      },
      async sendBatch() {
        const retained = owned.takeBatch();
        if (publishing) health.set({ kind: "sending", pending: records.length, dropped: dropped });

        const request = new AbortController();
        const deadline = new AbortController();
        const alarm = Promise.resolve().then(async () => {
          try {
            await ctx.clock.sleep(750, deadline.signal);
            request.abort(abortReasons.timeout);
          } catch (error) {
            if (!deadline.signal.aborted) throw error;
          }
        });

        let result: Telemetry.Delivery;
        try {
          result = await delivery.send(
            retained,
            AbortSignal.any([request.signal, stopRequests.signal]),
          );
        } finally {
          deadline.abort(abortReasons.done);
          await alarm;
        }

        const accepted = new Set(
          retained.filter((record) => (record.kind === "trace" ? result.traces : result.logs)),
        );
        records = records.filter((record) => !accepted.has(record));
        for (const record of accepted) queueBytes -= record.bytes;

        failed = !result.traces || !result.logs;
        if (publishing) {
          health.set(
            !failed
              ? {
                  kind: records.length ? "queued" : "idle",
                  pending: records.length,
                  dropped: dropped,
                }
              : {
                  kind: "failed",
                  failure: "Telemetry storage did not accept the batch",
                  pending: records.length,
                  dropped: dropped,
                },
          );
        }
      },
      /** The extension can write final data; a forced defer runs after its data owner is sealed. */
      async close(publishFinal: boolean) {
        if (state !== "open") return;

        state = "closing";
        publishing = false;
        stopTimer.abort(abortReasons.closed);

        const deadline = new AbortController();
        const alarm = Promise.resolve().then(async () => {
          try {
            await ctx.clock.sleep(1500, deadline.signal);
            stopRequests.abort(abortReasons.timeout);
          } catch (error) {
            if (!deadline.signal.aborted) throw error;
          }
        });

        try {
          await timer;
          if (pending) await pending;
          while (records.length && !stopRequests.signal.aborted) {
            await owned.flush();
            if (failed) break;
          }
        } finally {
          state = "closed";
          stopRequests.abort(abortReasons.closed);
          deadline.abort(abortReasons.done);
          await alarm;

          owned.flushConsole();
          dropped += records.length + consoleLines.length;
          consoleLines = [];
          consoleBytes = 0;
          records = [];
          queueBytes = 0;

          if (publishFinal) {
            health.set(
              failed
                ? {
                    kind: "failed",
                    failure: "Telemetry storage did not accept the batch",
                    pending: 0,
                    dropped,
                  }
                : { kind: "idle", pending: 0, dropped },
            );
          }
        }
      },
    };

    ctx.defer(() => owned.close(!ctx.signal.aborted));
    return owned;
  },
});

import type { Observe } from "@tinker/core";
import type { z } from "zod";

import type { span, logRecord, telemetryBatch } from "./records.server";

export declare namespace Telemetry {
  type Span = z.infer<typeof span>;
  type Log = z.infer<typeof logRecord>;
  type Batch = z.infer<typeof telemetryBatch>;
  type Side = Log["side"];
  type Health = { pending: number; dropped: number } & (
    | { kind: "idle" | "queued" | "sending" }
    | { kind: "failed"; failure: string }
  );
  type SpanBody = Omit<Span, "side">;
  /** Retained JSON is owned by the queue until storage accepts it. */
  type Record = { kind: "trace" | "log"; side: Side; json: string; bytes: number };
  type Delivery = { traces: boolean; logs: boolean };
  /** The span fields OTLP needs: a Core span fits, and so does one read back from a worker line. */
  type SpanFields = Pick<
    Observe.Span,
    | "traceId"
    | "spanId"
    | "parentSpanId"
    | "sampled"
    | "name"
    | "kind"
    | "start"
    | "end"
    | "status"
    | "error"
    | "attributes"
    | "events"
  >;
  /**
   * One line from the request thread to the telemetry worker: raw fields, no OTLP shape.
   * `encoded` 1 means every attribute value is already `encodeValue` output.
   */
  type Wire =
    | [
        tag: "s",
        side: Side,
        time: number,
        encoded: 0 | 1,
        traceId: string,
        spanId: string,
        parentSpanId: string | null,
        sampled: boolean,
        name: string,
        kind: Observe.Kind,
        start: number,
        end: number | null,
        status: "ok" | "failed" | null,
        error: string | null,
        attributes: { [key: string]: unknown },
        events: Observe.Event[],
      ]
    | [
        tag: "l",
        side: Side,
        encoded: 0 | 1,
        level: number,
        time: number,
        traceId: string | null,
        spanId: string | null,
        message: string,
        attributes: { [key: string]: unknown },
      ]
    | [tag: "b", batch: Batch];
}

/** Core attributes may contain bigint or cycles; one bad field must not lose its record.
 * @param value - From a span or log attribute; why: bound and safely encode its wire value.
 */
export function encodeValue(value: unknown): string {
  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return JSON.stringify(value).slice(0, 2048);
    case "bigint":
      return value.toString().slice(0, 2048);
    case "undefined":
      return "undefined";
  }
  try {
    return (
      JSON.stringify(value, (_key, entry) =>
        typeof entry === "bigint" ? entry.toString() : entry,
      ) ?? "undefined"
    ).slice(0, 2048);
  } catch {
    return "[Unserializable]";
  }
}

/**
 * The OTLP body of one span; the in-process observer and the worker drain share it.
 * @param span - From Core's export callback or a worker line; why: the fields to shape.
 * @param encoded - From a worker line's flag; why: its values are already `encodeValue` output.
 */
export function spanBody(span: Telemetry.SpanFields, encoded: boolean): Telemetry.SpanBody {
  const [startTimeUnixNano, endTimeUnixNano] = [span.start, span.end ?? span.start].map((time) => {
    const millis = Math.trunc(time);
    return millis === 0 ? "0" : `${millis}000000`;
  });
  const attributes = Object.entries(span.attributes)
    .slice(0, 31)
    .map(([key, value]) => ({
      key: key.slice(0, 256),
      value: { stringValue: encoded ? (value as string) : encodeValue(value) },
    }));
  attributes.push({ key: "tinker.kind", value: { stringValue: span.kind } });
  return {
    traceId: span.traceId,
    spanId: span.spanId,
    parentSpanId: span.parentSpanId,
    flags: span.sampled ? 1 : 0,
    name: span.name.slice(0, 256),
    kind: 1,
    startTimeUnixNano: startTimeUnixNano!,
    endTimeUnixNano: endTimeUnixNano!,
    attributes,
    events: span.events.slice(0, 32).map((event) => {
      const millis = Math.trunc(event.time);
      return {
        name: event.name.slice(0, 256),
        timeUnixNano: millis === 0 ? "0" : `${millis}000000`,
        attributes: Object.entries(event.attributes)
          .slice(0, 31)
          .map(([key, value]) => ({
            key: key.slice(0, 256),
            value: { stringValue: encoded ? (value as string) : encodeValue(value) },
          })),
      };
    }),
    status:
      span.status === "failed"
        ? { code: 2, message: String(span.error).slice(0, 2048) }
        : { code: 1 },
  };
}

